        var destLower = dest.toLowerCase();
        var allowed = destLower.indexOf("/tmp/pls") === 0
            || destLower.indexOf("/_savedata/track") === 0
            || destLower.indexOf("/savedata/track") === 0
            || destLower.indexOf("/_savedata/") === 0
            || destLower.indexOf("/savedata/") === 0
            || /\/track$/i.test(dest);
