        var lower = root.toLowerCase();
        var allowed = lower.indexOf("/tmp/pls") === 0
            || lower.indexOf("/_savedata/track") === 0
            || lower.indexOf("/savedata/track") === 0
            || lower.indexOf("/_savedata/charts") === 0
            || lower.indexOf("/savedata/charts") === 0
            || /\/track$/i.test(root);
